// Calculate 24 hours ago
const now = new Date();
const hoursAgo = 24;
const modifiedAfter = new Date(now.getTime() - (hoursAgo * 60 * 60 * 1000));

// Format for WooCommerce API (ISO 8601)
const modifiedAfterISO = modifiedAfter.toISOString();

return [{
  json: {
    modified_after: modifiedAfterISO
  }
}];

const products = [];

for (const item of $input.all()) {
  const product = item.json;

  const productText = `Product Name: ${product.name}
Description: ${product.description || product.short_description || ''}
Price: ${product.price}
Category: ${product.categories?.map(cat => cat.name).join(', ') || 'Uncategorized'}
SKU: ${product.sku || ''}
Stock Status: ${product.stock_status || ''}`;

  const metadata = {
    product_id: product.id.toString(),
    name: product.name,
    price: product.price,
    category: product.categories?.map(cat => cat.name).join(', ') || 'Uncategorized',
    category_ids: product.categories?.map(cat => cat.id) || [],
    sku: product.sku || '',
    url: product.permalink,
    stock_status: product.stock_status,
    image_url: product.images?.[0]?.src || '',
    last_modified: product.date_modified
  };

  products.push({
    json: {
      pageContent: productText,
      metadata: metadata
    }
  });
}

return products;

