const originalProducts = $('Get Updated Products').all();

console.log(`Retrieved ${originalProducts.length} products`);

// Return them in the same format they came in
return originalProducts;

// Extract product IDs for deletion AND pass through original products
const items = $input.all();

if (items.length === 0) {
  return [];
}

// Store original products to pass through
const originalProducts = items.map(item => item.json);

// Create deletion items
const deletionItems = [];
for (const item of items) {
  deletionItems.push({
    json: {
      product_id: item.json.id.toString(),
      _original_product: item.json  // Store original for later
    }
  });
}

return deletionItems;

// Get all items from merge
const allItems = $input.all();

// Find where WooCommerce products start and Supabase IDs start
// WooCommerce products have 'id', 'name', etc.
// Supabase response has 'product_id'
const wooProducts = allItems.filter(item => item.json.id !== undefined);
const supabaseResponse = allItems.filter(item => item.json.product_id !== undefined);

// If supabaseResponse is empty, check if it's nested
let supabaseProductIds;
if (supabaseResponse.length === 0) {
  // Data might be in a different format, check first item
  const firstItem = allItems.find(item => Array.isArray(item.json));
  if (firstItem && Array.isArray(firstItem.json)) {
    supabaseProductIds = firstItem.json.map(item => item.product_id);
  }
} else {
  supabaseProductIds = supabaseResponse.map(item => item.json.product_id);
}

const wooProductIds = new Set(wooProducts.map(item => item.json.id.toString()));

console.log(`✅ WooCommerce has ${wooProductIds.size} products`);
console.log(`📊 Supabase has ${supabaseProductIds.length} unique product IDs`);

// Find product IDs in Supabase that no longer exist in WooCommerce
const deletedProductIds = supabaseProductIds.filter(id => !wooProductIds.has(id));

if (deletedProductIds.length === 0) {
  console.log('✅ No deleted products found - database is in sync!');
  return [];
}

console.log(`🗑️ Found ${deletedProductIds.length} deleted products to remove from Supabase`);

// Return one item per deleted product ID for the deletion node
const results = [];
for (const productId of deletedProductIds) {
  results.push({
    json: {
      product_id: productId
    }
  });
}

return results;
